ALTER TABLE commerce.orders ADD COLUMN discount_minor bigint NOT NULL DEFAULT 0 CHECK(discount_minor>=0), ADD COLUMN coupon_code text;
ALTER TABLE commerce.inventory ADD COLUMN low_stock_threshold integer NOT NULL DEFAULT 3 CHECK(low_stock_threshold BETWEEN 0 AND 1000000);
CREATE TABLE commerce.customer_notes(organization_id uuid NOT NULL REFERENCES commerce.organizations(id),user_id uuid NOT NULL REFERENCES commerce.users(id),note text NOT NULL DEFAULT '' CHECK(length(note)<=2000),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id));
CREATE TABLE commerce.coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES commerce.organizations(id),code text NOT NULL CHECK(code ~ '^[A-Z0-9_-]{3,32}$'),kind text NOT NULL CHECK(kind IN ('percent','fixed')),value bigint NOT NULL CHECK(value>0),minimum_minor bigint NOT NULL DEFAULT 0 CHECK(minimum_minor>=0),maximum_discount_minor bigint CHECK(maximum_discount_minor>0),usage_limit integer NOT NULL CHECK(usage_limit BETWEEN 1 AND 1000000),per_customer_limit integer NOT NULL DEFAULT 1 CHECK(per_customer_limit BETWEEN 1 AND 1000),starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),CHECK(kind<>'percent' OR value<=100),UNIQUE(organization_id,code));
CREATE TABLE commerce.coupon_redemptions(coupon_id uuid NOT NULL REFERENCES commerce.coupons(id),order_id uuid NOT NULL REFERENCES commerce.orders(id),buyer_id uuid NOT NULL REFERENCES commerce.users(id),discount_minor bigint NOT NULL CHECK(discount_minor>0),PRIMARY KEY(coupon_id,order_id));
CREATE INDEX coupon_customer ON commerce.coupon_redemptions(coupon_id,buyer_id);
CREATE TABLE commerce.campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES commerce.organizations(id),title text NOT NULL CHECK(length(title) BETWEEN 3 AND 120),body text NOT NULL CHECK(length(body) BETWEEN 3 AND 1000),segment text NOT NULL CHECK(segment IN ('all','new','active','vip','at_risk')),recipient_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE commerce.user_notifications ADD COLUMN title text, ADD COLUMN body text, ADD COLUMN campaign_id uuid REFERENCES commerce.campaigns(id);
CREATE UNIQUE INDEX notification_campaign_recipient ON commerce.user_notifications(campaign_id,user_id) WHERE campaign_id IS NOT NULL;
CREATE TABLE commerce.return_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES commerce.orders(id),organization_id uuid NOT NULL REFERENCES commerce.organizations(id),buyer_id uuid NOT NULL REFERENCES commerce.users(id),reason text NOT NULL CHECK(length(reason) BETWEEN 5 AND 2000),status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','rejected','received')),seller_reply text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX returns_org_time ON commerce.return_requests(organization_id,created_at DESC);
CREATE INDEX orders_customer_history ON commerce.orders(organization_id,buyer_id,created_at DESC);
